
class Solution {
public:
    int maximumSaleItems(vector<vector<int>>& items, int budget) {
        int n = items.size();

        // Calculate the number of free copies generated by each item.
        vector<int> val(n);

        for (int i = 0; i < n; i++) {
            val[i] = 1;

            for (int j = 0; j < n; j++) {
                if (i != j && items[j][0] % items[i][0] == 0) {
                    val[i]++;
                }
            }
        }

        // Sort items by price in descending order.
        vector<int> order(n);
        iota(order.begin(), order.end(), 0);

        sort(order.begin(), order.end(), [&](int a, int b) {
            return items[a][1] > items[b][1];
        });

        const int NEG = -1000000000;

        // dpAll: best value using items processed so far.
        // dpWith: best value using at least one item
        // from the current price group.
        vector<int> dpAll(budget + 1, NEG);
        vector<int> dpWith(budget + 1, NEG);

        dpAll[0] = 0;

        int ans = 0;
        int pos = 0;

        while (pos < n) {
            int price = items[order[pos]][1];

            // Snapshot of items having strictly greater prices.
            vector<int> higher = dpAll;

            // Process all items with this price.
            while (pos < n &&
                   items[order[pos]][1] == price) {

                int id = order[pos];
                int gain = val[id];

                for (int c = budget; c >= price; c--) {
                    if (dpWith[c - price] != NEG) {
                        dpWith[c] = max(
                            dpWith[c],
                            dpWith[c - price] + gain
                        );
                    }

                    if (higher[c - price] != NEG) {
                        dpWith[c] = max(
                            dpWith[c],
                            higher[c - price] + gain
                        );
                    }

                    if (dpAll[c - price] != NEG) {
                        dpAll[c] = max(
                            dpAll[c],
                            dpAll[c - price] + gain
                        );
                    }
                }

                pos++;
            }

            // Spend remaining budget on additional copies
            // of an already activated cheapest item.
            for (int c = 0; c <= budget; c++) {
                if (dpWith[c] != NEG) {
                    ans = max(
                        ans,
                        dpWith[c] + (budget - c) / price
                    );
                }
            }
        }

        return ans;
    }
};
